// 1. Récupérer les données fusionnées
const data = $input.first().json;

// 2. Construire les lignes de prestation en filtrant les lignes vides
const rawLines = [
  { desc: data.line1_Desc, qty: data.line1_Qty, price: data.line1_Price },
  { desc: data.line2_Desc, qty: data.line2_Qty, price: data.line2_Price },
  { desc: data.line3_Desc, qty: data.line3_Qty, price: data.line3_Price },
];

const lines = rawLines
  .filter(line => line.desc !== "")
  .map(line => ({
    description: line.desc,
    quantity: line.qty,
    unitPrice: line.price,
    lineTotal: Math.round(line.qty * line.price * 100) / 100,
  }));

// 3. Calculer les totaux
const totalHT = Math.round(lines.reduce((sum, l) => sum + l.lineTotal, 0) * 100) / 100;
const vatAmount = Math.round(totalHT * (data.vatRate / 100) * 100) / 100;
const totalTTC = Math.round((totalHT + vatAmount) * 100) / 100;

// 4. Déterminer le préfixe et le délai selon le type de document
const isInvoice = data.documentType === "Facture";
const prefix = isInvoice ? data.invoicePrefix : data.quotePrefix;
const validityDays = isInvoice ? data.invoiceDueDays : data.quoteValidityDays;

// 5. Générer le numéro de document, avec l'heure locale suisse (gère automatiquement
//    le changement heure été/hiver, contrairement à un décalage fixe)
const issueDate = new Date(data.submittedAt);

function zurichParts(date) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Zurich',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).formatToParts(date);
  const map = {};
  parts.forEach(p => { map[p.type] = p.value; });
  return map;
}

const zp = zurichParts(issueDate);
const datePart = `${zp.year}${zp.month}${zp.day}`;
const timePart = `${zp.hour}${zp.minute}`;
const documentNumber = `${prefix}${datePart}-${timePart}`;

// 6. Calculer la date d'échéance / validité
const dueDate = new Date(issueDate);
dueDate.setDate(dueDate.getDate() + validityDays);

// 7. Retourner un objet propre et structuré pour le template PDF
return [{
  json: {
    documentType: data.documentType,
    documentNumber,
    issueDate: `${zp.year}-${zp.month}-${zp.day}`,
    dueDate: dueDate.toISOString().slice(0, 10),
    issuer: {
      name: data.issuerName,
      address: data.issuerAddress,
      city: data.issuerCity,
      email: data.issuerEmail,
      phone: data.issuerPhone,
      iban: data.issuerIBAN,
      vatNumber: data.issuerVATNumber,
      paymentTerms: data.paymentTerms,
    },
    client: {
      name: data.clientName,
      address: data.clientAddress,
      email: data.clientEmail,
    },
    lines,
    vatRate: data.vatRate,
    totalHT,
    vatAmount,
    totalTTC,
  }
}];

const data = $input.first().json;

// Sépare "Route de la Gare 5" en rue + numéro
function parseStreet(streetFull) {
  const match = (streetFull || '').match(/^(.*?)\s+(\d+\w*)$/);
  return match
    ? { street: match[1].trim(), buildingNb: match[2] }
    : { street: (streetFull || '').trim(), buildingNb: '' };
}

// Sépare "1680 Romont" en NPA + ville
function parseCity(cityFull) {
  const match = (cityFull || '').match(/^(\d{4})\s+(.*)$/);
  return match
    ? { postalCode: match[1], town: match[2].trim() }
    : { postalCode: '', town: (cityFull || '').trim() };
}

const { street, buildingNb } = parseStreet(data.issuer.address);
const { postalCode, town } = parseCity(data.issuer.city);
const ibanClean = (data.issuer.iban || '').replace(/\s/g, '');

// Construction du payload SPC (Swiss Payments Code), norme v2.3
const spcLines = [
  'SPC',                            // Type
  '0200',                           // Version
  '1',                              // Encodage UTF-8
  ibanClean,                        // IBAN créancier
  'S',                              // Adresse structurée
  data.issuer.name,
  street,
  buildingNb,
  postalCode,
  town,
  'CH',
  '', '', '', '', '', '', '',       // Bloc "créancier final" — non utilisé
  data.totalTTC.toFixed(2),         // Montant
  'CHF',
  '', '', '', '', '', '', '',       // Bloc débiteur — laissé vide (simplification V1)
  'NON',                            // Pas de référence structurée
  '',
  `Facture ${data.documentNumber}`, // Message libre
  'EPD',                            // Fin des données de paiement
  '',                                // Informations de facturation — vide
];

const spcPayload = spcLines.join('\r\n');

return [{ json: { ...data, spcPayload } }];

const PDFDocument = require('pdfkit');

const data = $('Générer SPC').first().json;
const qrBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

const ACCENT = '#2563eb';
const TEXT = '#1a1a1a';
const MUTED = '#6b7280';

const fmt = (n) => n.toFixed(2) + ' CHF';

return new Promise((resolve, reject) => {
  const doc = new PDFDocument({ size: 'A4', margin: 56 });
  const chunks = [];
  doc.on('data', (c) => chunks.push(c));
  doc.on('error', reject);
  doc.on('end', async () => {
    try {
      const pdfBuffer = Buffer.concat(chunks);
      const binary = await this.helpers.prepareBinaryData(
        pdfBuffer,
        `${data.documentNumber}.pdf`,
        'application/pdf'
      );
      resolve([{ json: data, binary: { data: binary } }]);
    } catch (err) {
      reject(err);
    }
  });

  const pageWidth = doc.page.width - doc.page.margins.left - doc.page.margins.right;
  const startX = doc.page.margins.left;

  // ---- En-tête : émetteur (gauche) + titre document (droite) ----
  doc.fontSize(15).fillColor(ACCENT).font('Helvetica-Bold').text(data.issuer.name, startX, 56);
  doc.fontSize(9.5).fillColor(MUTED).font('Helvetica')
    .text(data.issuer.address)
    .text(data.issuer.city)
    .text(`${data.issuer.email} · ${data.issuer.phone}`);

  doc.fontSize(22).fillColor(ACCENT).font('Helvetica-Bold')
    .text(data.documentType.toUpperCase(), startX, 56, { width: pageWidth, align: 'right' });
  doc.fontSize(9.5).fillColor(MUTED).font('Helvetica')
    .text(`N° ${data.documentNumber}`, { width: pageWidth, align: 'right' })
    .text(`Émis le ${data.issueDate}`, { width: pageWidth, align: 'right' })
    .text(`Échéance ${data.dueDate}`, { width: pageWidth, align: 'right' });

  // ---- Bloc client ----
  doc.moveDown(3);
  doc.fontSize(8.5).fillColor(MUTED).font('Helvetica').text('ADRESSÉ À', startX);
  doc.fontSize(12).fillColor(TEXT).font('Helvetica-Bold').text(data.client.name, startX);
  doc.fontSize(9.5).fillColor(MUTED).font('Helvetica')
    .text(data.client.address, startX)
    .text(data.client.email, startX);

  // ---- Tableau des lignes : 4 colonnes à largeurs fixes ----
  doc.moveDown(1.5);
  const tableTop = doc.y;
  const gap = 10;
  const qtyWidth = 40;
  const priceWidth = 75;
  const totalWidth = 90;
  const descWidth = pageWidth - (qtyWidth + gap + priceWidth + gap + totalWidth + gap);

  const col = {
    desc: startX,
    qty: startX + descWidth + gap,
    price: startX + descWidth + gap + qtyWidth + gap,
    total: startX + descWidth + gap + qtyWidth + gap + priceWidth + gap,
  };

  doc.fontSize(8.5).fillColor(MUTED).font('Helvetica-Bold');
  doc.text('DESCRIPTION', col.desc, tableTop, { width: descWidth });
  doc.text('QTÉ', col.qty, tableTop, { width: qtyWidth, align: 'right' });
  doc.text('PRIX UNITAIRE', col.price, tableTop, { width: priceWidth, align: 'right' });
  doc.text('TOTAL', col.total, tableTop, { width: totalWidth, align: 'right' });

  doc.moveTo(startX, tableTop + 14).lineTo(startX + pageWidth, tableTop + 14).strokeColor(ACCENT).lineWidth(1.5).stroke();

  let rowY = tableTop + 22;
  doc.font('Helvetica').fontSize(10).fillColor(TEXT);
  for (const line of data.lines) {
    doc.text(line.description, col.desc, rowY, { width: descWidth });
    doc.text(String(line.quantity), col.qty, rowY, { width: qtyWidth, align: 'right' });
    doc.text(fmt(line.unitPrice), col.price, rowY, { width: priceWidth, align: 'right' });
    doc.text(fmt(line.lineTotal), col.total, rowY, { width: totalWidth, align: 'right' });
    doc.moveTo(startX, rowY + 18).lineTo(startX + pageWidth, rowY + 18).strokeColor('#e5e7eb').lineWidth(0.5).stroke();
    rowY += 26;
  }

  // ---- Totaux ----
  const totalsX = startX + pageWidth - 200;
  let totalsY = rowY + 10;
  doc.fontSize(10).fillColor(TEXT).font('Helvetica');
  doc.text('Total HT', totalsX, totalsY, { width: 100 });
  doc.text(fmt(data.totalHT), totalsX + 100, totalsY, { width: 100, align: 'right' });
  totalsY += 18;
  doc.text(`TVA (${data.vatRate}%)`, totalsX, totalsY, { width: 100 });
  doc.text(fmt(data.vatAmount), totalsX + 100, totalsY, { width: 100, align: 'right' });
  totalsY += 22;
  doc.moveTo(totalsX, totalsY - 4).lineTo(totalsX + 200, totalsY - 4).strokeColor(ACCENT).lineWidth(1.5).stroke();
  doc.fontSize(13).fillColor(ACCENT).font('Helvetica-Bold');
  doc.text('Total TTC', totalsX, totalsY);
  doc.text(fmt(data.totalTTC), totalsX + 100, totalsY, { width: 100, align: 'right' });

  // ---- Pied de page ----
  let footerY = totalsY + 40;
  doc.fontSize(9).fillColor(MUTED).font('Helvetica');
  doc.text(data.issuer.paymentTerms, startX, footerY);
  doc.text(
    `IBAN : ${data.issuer.iban}` + (data.issuer.vatNumber ? ` · N° TVA : ${data.issuer.vatNumber}` : ''),
    startX
  );

  // ---- Section paiement (QR-facture) — uniquement sur les factures ----
  if (data.documentType === 'Facture') {
    let paymentY = doc.y + 30;
    doc.moveTo(startX, paymentY).lineTo(startX + pageWidth, paymentY).dash(3, { space: 2 }).strokeColor(MUTED).lineWidth(1).stroke();
    doc.undash();
    paymentY += 20;

    doc.image(qrBuffer, startX, paymentY, { width: 100, height: 100 });

    const detailsX = startX + 124;
    doc.fontSize(8).fillColor(MUTED).font('Helvetica').text('SECTION PAIEMENT', detailsX, paymentY);
    doc.fontSize(9).fillColor(TEXT).font('Helvetica')
      .text(`Compte / IBAN : ${data.issuer.iban}`, detailsX)
      .text(`Créditeur : ${data.issuer.name}, ${data.issuer.address}, ${data.issuer.city}`, detailsX);
    doc.fontSize(12).fillColor(ACCENT).font('Helvetica-Bold').text(`Montant : ${fmt(data.totalTTC)}`, detailsX);
  }

  doc.end();
});

const body = $input.first().json.body;

return [{
  json: {
    documentType: body.documentType,
    clientName: body.clientName,
    clientAddress: body.clientAddress,
    clientEmail: body.clientEmail,
    line1_Desc: body.line1_Desc,
    line1_Qty: Number(body.line1_Qty),
    line1_Price: Number(body.line1_Price),
    line2_Desc: body.line2_Desc || '',
    line2_Qty: Number(body.line2_Qty) || 0,
    line2_Price: Number(body.line2_Price) || 0,
    line3_Desc: body.line3_Desc || '',
    line3_Qty: Number(body.line3_Qty) || 0,
    line3_Price: Number(body.line3_Price) || 0,
    vatRate: Number(body.vatRate),
    submittedAt: new Date().toISOString(),
  }
}];
